  (pc = P_A_CONFIG_GET_BOOL /\ pch = P_A_CGB_HAND) \/ (pc = P_A_CONFIG_GET_INT /\ pch = P_A_CGI_HAND) \/ (pc = P_A_CONFIG_GET_LONG /\ pch = P_A_CGL_HAND).

